]}$veri$::jsonb as d;

insert into public.uzmanlar (slug, unvan_oneki, ad, soyad, unvan, foto_yolu, sehir, ilce, gorusme_online, gorusme_yuzyuze,
  yeni_danisan, deneyim_yili, cinsiyet, diller, yas_gruplari, kisa_tanitim, hakkinda, seans_suresi, online_platform,
  muayenehane_adres, durum, yayin_tarihi, ornek, kabul_durumu_guncellenme, olusturulma, guncellenme)
select u->>'slug', u->>'onek', u->>'ad', u->>'soyad', u->>'unvan', u->>'foto', u->>'sehir', u->>'ilce',
  (u->>'on')::boolean, (u->>'yy')::boolean, (u->>'yeni')::boolean, (u->>'dy')::smallint, u->>'cins',
  array(select jsonb_array_elements_text(u->'dil')), array(select jsonb_array_elements_text(u->'grup')),
  u->>'tan', u->>'hak', u->>'sure', u->>'plat', u->>'adr',
  (case when (u->>'yay')::boolean then 'yayinda' else 'incelemede' end)::public.uzman_durumu,
  case when (u->>'yay')::boolean then (u->>'gun')::timestamptz end, true,
  (u->>'kab')::timestamptz, (u->>'gun')::timestamptz, (u->>'gun')::timestamptz
from _ornek, jsonb_array_elements(d->'uz') u;

insert into public.uzman_uzmanliklar (uzman_id, alan_id, sira)
select z.id, a.id, (e.ord - 1)::smallint
from _ornek, jsonb_array_elements(d->'uz') u
join public.uzmanlar z on z.slug = u->>'slug'
cross join lateral jsonb_array_elements_text(coalesce(u->'alan', '[]')) with ordinality e(ad, ord)
join public.uzmanlik_alanlari a on a.ad = e.ad;

insert into public.uzman_yaklasimlar (uzman_id, yaklasim_id, sira)
select z.id, y.id, (e.ord - 1)::smallint
from _ornek, jsonb_array_elements(d->'uz') u
join public.uzmanlar z on z.slug = u->>'slug'
cross join lateral jsonb_array_elements_text(coalesce(u->'yak', '[]')) with ordinality e(ad, ord)
join public.yaklasimlar y on y.ad = e.ad;

insert into public.uzman_egitimler (uzman_id, tur, metin, sira)
select z.id, t.tur, e.metin, (e.ord - 1)::smallint
from _ornek, jsonb_array_elements(d->'uz') u
join public.uzmanlar z on z.slug = u->>'slug'
cross join lateral (values ('egitim', 'eg'), ('sertifika', 'ser')) t(tur, anahtar)
cross join lateral jsonb_array_elements_text(coalesce(u->t.anahtar, '[]')) with ordinality e(metin, ord);

insert into public.uzman_sss (uzman_id, soru, cevap, sira)
select z.id, e.x->>'soru', e.x->>'cevap', (e.ord - 1)::smallint
from _ornek, jsonb_array_elements(d->'uz') u
join public.uzmanlar z on z.slug = u->>'slug'
cross join lateral jsonb_array_elements(coalesce(u->'sss', '[]')) with ordinality e(x, ord);

insert into public.uzman_iletisim (uzman_id, telefon, whatsapp, eposta, telefon_yayinda, whatsapp_yayinda, eposta_yayinda)
select z.id, u->>'tel', u->>'wa', u->>'ep', coalesce((u->>'telA')::boolean, false),
  coalesce((u->>'waA')::boolean, false), coalesce((u->>'epA')::boolean, false)
from _ornek, jsonb_array_elements(d->'uz') u
join public.uzmanlar z on z.slug = u->>'slug';

insert into public.yazilar (uzman_id, slug, baslik, ozet, kategori, okuma_dakika, durum, yayin_tarihi, olusturulma, guncellenme)
select z.id, y->>'slug', y->>'bas', y->>'oz', y->>'kat', (y->>'dk')::smallint, 'yayinda',
  (y->>'tarih')::timestamptz, (y->>'tarih')::timestamptz, (y->>'tarih')::timestamptz
from _ornek, jsonb_array_elements(d->'yz') y
join public.uzmanlar z on z.slug = y->>'yazar';
drop table _ornek;
